using System.Text.Json;
namespace RisingLands;
public record RecruitRule(int Type,int Food,int Rock,int Parts,int Duration,int Health,int AnimationCount,int AnimationDelay);
public record RecruitCatalog(List<RecruitRule> Rules,int SanctuaryCapacity);
public sealed class Recruitment {public int Owner{get;set;}public int BuildingSlot{get;set;}public int SettlerSlot{get;set;}public int Type{get;set;}public int Progress{get;set;}=1;public bool Finished{get;set;}public int SourceBuildingSlot{get;set;}=-1;public int TravelCell{get;set;}=-1;public bool Arrived{get;set;}=true;public bool LegacyBarracks{get;set;}}
public sealed partial class Simulation {
    public static readonly RecruitCatalog RecruitData=JsonSerializer.Deserialize<RecruitCatalog>(File.ReadAllText(PackageLayout.FromBase("Content/Data/recruitment_rules.json")),new JsonSerializerOptions{PropertyNameCaseInsensitive=true,PropertyNamingPolicy=JsonNamingPolicy.SnakeCaseLower})!;
    public List<Recruitment> Recruitments{get;private set;}=new();Dictionary<int,Actor> InitialActors;
    public RecruitRule TrainingRule(int type)=>RecruitData.Rules.First(r=>r.Type==type);
    public int Settlers(int building)=>World.BuildingResidents.GetValueOrDefault(building,new()).Count(slot=>World.Units.FirstOrDefault(a=>a.Slot==slot) is {} u&&u.Type==9&&!ResearchReserved(slot)&&!Recruitments.Any(t=>t.SettlerSlot==slot&&!t.Finished&&t.SourceBuildingSlot>=0));
    public bool UnitUnlocked(int type)=>UnlockData.Technologies.Any(t=>ProductionUnlocks.GetValueOrDefault(t.Key,Array.Empty<int>()).Contains(type)&&TechnologyApplied(t));
    public bool Recruit(int type,int buildingSlot=-1){if(buildingSlot>=0&&!CanRecruit(type,buildingSlot))return false;if(!UnitUnlocked(type))return false;if(type is not (5 or 6 or 7)){if(buildingSlot<0)buildingSlot=World.Buildings.FirstOrDefault(b=>b.Owner==0&&CanRecruit(type,b.Slot))?.Slot??-1;return RecruitSoldier(type,buildingSlot);}if(!RecruitData.Rules.Any(r=>r.Type==type))return false;var rule=TrainingRule(type);if(World.Resources[0]<rule.Food||World.Resources[4]<rule.Rock||World.Resources[8]<rule.Parts)return false;
        foreach(var b in World.Buildings.Where(b=>b.Owner==0&&b.Type==2&&(buildingSlot<0||b.Slot==buildingSlot))){if(Recruitments.Any(t=>t.BuildingSlot==b.Slot&&!t.Finished))continue;int slot=World.BuildingResidents.GetValueOrDefault(b.Slot,new()).FirstOrDefault(slot=>World.Units.FirstOrDefault(a=>a.Slot==slot) is {} u&&u.Owner==0&&u.Type==9&&u.LegacyState==14&&!ResearchReserved(slot)&&!Recruitments.Any(t=>t.SettlerSlot==slot&&!t.Finished),-1);if(slot<0)continue;
            World.Resources[0]-=(ushort)rule.Food;World.Resources[4]-=(ushort)rule.Rock;World.Resources[8]-=(ushort)rule.Parts;Recruitments.Add(new Recruitment{Type=type,SettlerSlot=slot,BuildingSlot=b.Slot});return true;}return false;
    }
    void RecruitStep(){StartTrainingQueues();foreach(var job in Recruitments.Where(t=>!t.Finished)){if(IsFifthMission&&ClanEliminated(job.Owner))continue;if(RetireLockedEnemyRecruitment(job))continue;var rule=TrainingRule(job.Type);if(!World.Buildings.Any(b=>b.Slot==job.BuildingSlot)||!World.Units.Any(a=>a.Slot==job.SettlerSlot&&a.Health>0))continue;if(!job.Arrived){var traveler=World.Units.First(a=>a.Slot==job.SettlerSlot);var trainingBuilding=World.Buildings.First(b=>b.Slot==job.BuildingSlot);if(Feeding(traveler)||!ReachBuildingInteraction(traveler,trainingBuilding,job.TravelCell))continue;traveler.LegacyState=14;job.Arrived=true;continue;}job.Progress=Math.Min(rule.Duration,job.Progress+100+TrainingPopulation(job.BuildingSlot)*100/Math.Max(1,ResidentCapacity(World.Buildings.First(b=>b.Slot==job.BuildingSlot))));if(job.Progress<rule.Duration)continue;var b=World.Buildings.First(b=>b.Slot==job.BuildingSlot);int exit=BuildingExit(b);
        if(exit<0)continue;var actor=World.Units.First(u=>u.Slot==job.SettlerSlot);actor.Type=job.Type;actor.LegacyState=7;actor.Health=rule.Health;actor.Direction=13;actor.AnimationFrame=0;actor.AnimationCounter=0;actor.AnimationCount=rule.AnimationCount;actor.AnimationDelay=rule.AnimationDelay;PlaceAtExit(actor,b,exit);actor.Route.Clear();actor.Mana=0;actor.RepairTarget=-1;actor.PetrifiedUntil=actor.ArmoredUntil=actor.CastAnimationUntil=0;job.Finished=true;EmitUnitSound(actor,6,4);EmitBuildingSound(b,0x26);
    }}
    Actor ExpectedActor(int slot,IEnumerable<Recruitment> jobs,Dictionary<int,int>? reversions=null){var original=InitialActors[slot];var history=jobs.Where(t=>t.SettlerSlot==slot).ToArray();if(reversions!=null&&reversions.TryGetValue(slot,out int count)){original=ColonistTemplate(slot);if(history.Length<=count)return original;}var job=history.LastOrDefault();if(job==null)return original;if(!job.Finished){if(job.SourceBuildingSlot<0)return original;var pending=JsonSerializer.Deserialize<Actor>(JsonSerializer.Serialize(original))!;pending.LegacyState=job.Arrived?14:7;return pending;}var r=TrainingRule(job.Type);return new Actor{Slot=slot,Type=r.Type,Owner=original.Owner,LegacyState=7,Health=r.Health,AnimationCount=r.AnimationCount,AnimationDelay=r.AnimationDelay};}
    void ValidateRecruitSave(Save s){if(s.Recruitments==null||s.Recruitments.Count>10000)throw new InvalidDataException("Invalid recruitment count");var slots=new HashSet<int>();var bases=new HashSet<int>();foreach(var t in s.Recruitments){if((t.SourceBuildingSlot<0)!=(t.Type is 5 or 6 or 7)||!RecruitData.Rules.Any(r=>r.Type==t.Type)||!t.Finished&&!slots.Add(t.SettlerSlot)||!InitialBuildings.Concat(s.Constructions.Where(Complete).Select(c=>new Building(c.Id,c.Type,c.Owner,c.Cell))).Any(b=>b.Slot==t.BuildingSlot&&ValidProductionBuilding(t,b)&&b.Owner==t.Owner)||!t.Finished&&!World.BuildingResidents.GetValueOrDefault(t.SourceBuildingSlot<0?t.BuildingSlot:t.SourceBuildingSlot,new()).Contains(t.SettlerSlot)||!InitialActors.TryGetValue(t.SettlerSlot,out var u)||t.Owner is <0 or >3||!t.Finished&&ExpectedTradeOwner(t.SettlerSlot,s.Special)!=t.Owner||(u.Type!=9||u.LegacyState!=14)&&!(s.Reversions?.ContainsKey(t.SettlerSlot)??false))throw new InvalidDataException("Invalid recruitment identity");var r=TrainingRule(t.Type);if(t.LegacyBarracks&&t.Type is not (11 or 12 or 14)||t.SourceBuildingSlot>=0&&t.SourceBuildingSlot!=t.BuildingSlot||t.SourceBuildingSlot>=0&&(t.TravelCell<0||t.TravelCell>=65536)||t.Progress<1||t.Progress>r.Duration||t.Finished&&t.Progress!=r.Duration||!t.Finished&&s.Units.Any(a=>a.Slot==t.SettlerSlot&&a.Health>0)&&!bases.Add(t.BuildingSlot))throw new InvalidDataException("Invalid recruitment progress");}}
}
